(5901, 'Joshua 19:42', 'Joshua', 19, 42, '&nbsp;شعلبين، ايالون، اِتلاه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5902, 'Joshua 19:43', 'Joshua', 19, 43, '&nbsp;ايلون، تمنت، عقرون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5903, 'Joshua 19:44', 'Joshua', 19, 44, '&nbsp;التِقيه، جبتون، بعلات،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5904, 'Joshua 19:45', 'Joshua', 19, 45, '&nbsp;يهود، بنى‌برق، جات رِمون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5905, 'Joshua 19:46', 'Joshua', 19, 46, '&nbsp;مےيرقون، رقون او داسې د يافا نه ګېرچاپېره علاقه هم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5906, 'Joshua 19:47', 'Joshua', 19, 47, '&nbsp;کله چې د دان د خلقو نه زمکه لاړه، نو هغوئ لشم ته لاړل او حمله يې پرې وکړه. هغه يې قبضه کړو، د دې خلق يې ووژل او په مُلک باندې يې خپله دعوىٰ وکړه. هغوئ هلته اوسېدل او د هغه ښار نوم يې د لشم نه دان ته بدل کړو، يعنې د خپل پلار نيکۀ نوم دان يې ورباندې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5907, 'Joshua 19:48', 'Joshua', 19, 48, '&nbsp;دا ښارونه او د دې کلى په هغه مُلک کښې وُو کوم چې د دان قبيلې کورَنو ته مِلاو شوى وُو چې خپل ميراث يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5908, 'Joshua 19:49', 'Joshua', 19, 49, '&nbsp;کله چې بنى اِسرائيلو د زمکې تقسيمول ختم کړل، نو هغوئ د نون زوئ يشوَع له د زمکې يوه حِصه ورکړه چې د هغۀ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5909, 'Joshua 19:50', 'Joshua', 19, 50, '&nbsp;لکه څنګه چې مالِک خُدائ حُکم کړے وو، هغوئ يشوَع له هغه ښار ورکړو چې کوم يې غوښتے وو، يعنې د غرونو په مُلک اِفرائيم کښې د تمنت‌سِرح ښار هغۀ بيا جوړ کړو او هغه په کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5910, 'Joshua 19:51', 'Joshua', 19, 51, '&nbsp;اِلى‌عزر اِمام، د نون زوئ يشوَع، د بنى اِسرائيلو د کورَنو مشرانو د زمکې دا برخې د پچې په ذريعه حواله کړې او په سيلا کښې يې د مالِک خُدائ سره د مشورې په مطابق د مالِک خُدائ د حضور مقدسې خېمې د دروازې په خولۀ کښې داسې وکړل، نو په دې طريقه هغوئ د زمکې تقسيمول ختم کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5911, 'Joshua 20:1', 'Joshua', 20, 1, '&nbsp;نو مالِک خُدائ يشوَع ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5912, 'Joshua 20:2', 'Joshua', 20, 2, '&nbsp;چې، ”بنى اِسرائيلو ته ووايه، د پناه دپاره ښارونه خوښ کړئ لکه څنګه چې ما موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5913, 'Joshua 20:3', 'Joshua', 20, 3, '&nbsp;کله چې څوک په غلطۍ سره يو کس ووژنى نو هغه کس هغه ځائ ته تښتېدے شى چې د بدل اخستونکو نه په امان کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5914, 'Joshua 20:4', 'Joshua', 20, 4, '&nbsp;نو هغه کس دې د دې ښارونو نه يو ښار ته وتښتى او د ښار د دروازې سره د جرګې ځائ ته دې لاړ شى او چې څۀ شوى وُو نو هغه دې مشرانو ته بيان کړى. نو بيا به هغه کس له اجازت ورکړى چې ښار ته ورننوځى او د اوسېدو دپاره به يو ځائ ورکړى، نو هغه به هلته اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5915, 'Joshua 20:5', 'Joshua', 20, 5, '&nbsp;کۀ هغه کس هلته هم ورپسې لاړ شى چې کوم بدل اخستل غواړى، نو د هغه ښار خلق دې هغوئ هيڅکله هغۀ ته نۀ حواله کوى. د ښار خلق به يې خامخا بچ کوى ځکه هغۀ به قصداً نۀ بلکې په غلطۍ سره کس وژلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5916, 'Joshua 20:6', 'Joshua', 20, 6, '&nbsp;هغه به تر هغې پورې په هغه ښار کښې ايسار وى چې تر کومې پورې هغه مشر اِمام ژوندے وى او د هغۀ سره عوامى عدالت وشى. بيا دې هغه په خپل ښار کښې کور ته واپس لاړ شى، د کوم نه چې هغه راتښتېدلے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5917, 'Joshua 20:7', 'Joshua', 20, 7, '&nbsp;نو هغوئ د اُردن نمرپرېواتۀ طرف ته د نفتالى غرونو په مُلک کښې د ګليل قادِس خوښ کړو، د اِفرائيم غرونو په مُلک کښې شِکم، او د يهوداه غرونو په مُلک کښې يې حبرون خوښ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5918, 'Joshua 20:8', 'Joshua', 20, 8, '&nbsp;هغوئ د اُردن نمرخاتۀ طرف ته، د يريحو نمرخاتۀ طرف ته د صحرا په اوچت ځائ باندې او د روبين په علاقه کښې بصر خوښ کړو، د جاد په علاقه جِلعاد کښې رامات، د منسى په علاقه کښې او په بسن کښې يې جولان خوښ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5919, 'Joshua 20:9', 'Joshua', 20, 9, '&nbsp;دا د ټولو بنى اِسرائيلو او د پردى مُلک هغه ټولو مسافرو دپاره د پناه ښارونه وُو کوم مسافر چې د هغوئ سره اوسېدل. هر چا به چې هم په غلطۍ سره يو کس وژلے وو نو هغۀ ته به د هغه کس نه په هغه ښارونو کښې پناه مِلاوېده چا به چې بدل اخستل غوښتل، چې ترڅو پورې په هغۀ باندې په عوامى عدالت کښې فېصله نۀ وه شوې نو هيڅ څوک به نۀ شول وژلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5920, 'Joshua 21:1', 'Joshua', 21, 1, '&nbsp;د ليوى قبيلې د کورَنو مشران اِلى‌عزر اِمام، د نون زوئ يشوَع او د ټولو بنى اِسرائيلو د قبيلو مشرانو له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5921, 'Joshua 21:2', 'Joshua', 21, 2, '&nbsp;هلته د کنعان په مُلک سيلا کښې مشرانو هغوئ ته ووئيل، ”مالِک خُدائ د موسىٰ په ذريعه حُکم کړے دے چې مونږ له به د اوسېدو دپاره ښارونه راکولے شى او داسې د دې نه ګېرچاپېره زمونږ د څاروو دپاره به د څرن زمکه راکولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5922, 'Joshua 21:3', 'Joshua', 21, 3, '&nbsp;نو د مالِک خُدائ د حُکم په مطابق بنى اِسرائيلو د خپلو علاقو نه ليويانو له خاص ښارونه او د څرن زمکې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5923, 'Joshua 21:4', 'Joshua', 21, 4, '&nbsp;وړومبى ښارونه د ليوى خاندان د قُهات قبيلو ته حواله کړے شول. هغه خاندان کوم چې د هارون اِمام اولاد وُو هغوئ ته د يهوداه، شمعون او بنيامين د علاقو نه ديارلس ښارونه حواله کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5924, 'Joshua 21:5', 'Joshua', 21, 5, '&nbsp;د قُهات باقى پاتې قبيلې ته د اِفرائيم، دان او نمرپرېواتۀ طرف ته منسى د علاقو نه لس ښارونه حواله کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5925, 'Joshua 21:6', 'Joshua', 21, 6, '&nbsp;د جيرسون قبيلې ته د يساکار، آشر، نفتالى او نمرخاتۀ طرف ته منسى د علاقو نه ديارلس ښارونه حواله کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5926, 'Joshua 21:7', 'Joshua', 21, 7, '&nbsp;د مرارى قبيلې کورَنو ته د روبين، جاد او زبولون علاقو نه دولس ښارونه حواله کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5927, 'Joshua 21:8', 'Joshua', 21, 8, '&nbsp;بنى اِسرائيلو د پچې په ذريعه دا ښارونه او د دې د څرن زمکې ليويانو ته حواله کړې، هم هغه شان چې څنګه مالِک خُدائ د موسىٰ په ذريعه حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5928, 'Joshua 21:9', 'Joshua', 21, 9, '&nbsp;دا د هغه ښارونو نومونه دى کوم چې د يهوداه او شمعون د علاقو نه ورکړے شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5929, 'Joshua 21:10', 'Joshua', 21, 10, '&nbsp;دا د هارون اولاد له ورکړے شوى وُو چې هغوئ د قُهات قبيله وه، چې هغوئ د ليويانو اولاد وو، ځکه چې اول هغوئ ته علاقه حواله کولے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5930, 'Joshua 21:11', 'Joshua', 21, 11, '&nbsp;هغوئ له د قِريَت‌اربع ښار ورکړے شو (اربع د عناق پلار وو)، اربع اوس حبرون بللے شى، دا د يهوداه د غرونو په مُلک کښې دے، د دې سره د دې نه ګېرچاپېره د څرن زمکه هم ورکړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5931, 'Joshua 21:12', 'Joshua', 21, 12, '&nbsp;خو د هغه ښار پټى او نزدې کلى د مخکښې نه د يفُنه زوئ کالب له په ميراث کښې ورکړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5932, 'Joshua 21:13', 'Joshua', 21, 13, '&nbsp;دا ښارونه سره د څرن د زمکې د هارون اِمام اولاد ته حواله شوى وُو، حبرون کوم چې د پناه ښار وو، او لِبناه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5933, 'Joshua 21:14', 'Joshua', 21, 14, '&nbsp;يتير، استموع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5934, 'Joshua 21:15', 'Joshua', 21, 15, '&nbsp;حولون، دبير،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5935, 'Joshua 21:16', 'Joshua', 21, 16, '&nbsp;عين، يُوطه او بيت‌شمس، چې د دې سره د څرن زمکې هم وې، نهۀ ښارونه د يهوداه او شمعون دواړو قبيلو نه ورته حواله کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5936, 'Joshua 21:17', 'Joshua', 21, 17, '&nbsp;د بنيامين د علاقې نه هغوئ له څلور ښارونه ورکړے شوى وُو، جبعون، جبعه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5937, 'Joshua 21:18', 'Joshua', 21, 18, '&nbsp;عنتوت او د علمون ښارونه، چې د دې سره د څرن زمکې هم وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5938, 'Joshua 21:19', 'Joshua', 21, 19, '&nbsp;ټول ديارلس ښارونه، سره د څرن د زمکې د هارون اولاد اِمامانو له ورکړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5939, 'Joshua 21:20', 'Joshua', 21, 20, '&nbsp;د ليوى قبيلې د قُهات قبيلې نورو کورَنو ته د اِفرائيم د علاقې نه څۀ ښارونه حواله کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5940, 'Joshua 21:21', 'Joshua', 21, 21, '&nbsp;هغوئ له څلور ښارونه ورکړے شوى وُو، شِکم او د اِفرائيم د غرونو په مُلک کښې د دې د څرن زمکه (شِکم د پناه يو ښار وو)، جزر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5941, 'Joshua 21:22', 'Joshua', 21, 22, '&nbsp;قِبضيم او د بيت‌حورون ښارونه، چې د څرن زمکې د دې سره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5942, 'Joshua 21:23', 'Joshua', 21, 23, '&nbsp;د دان د علاقې نه هغوئ له څلور ښارونه ورکړے شوى وُو، التِقيه، جبتون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5943, 'Joshua 21:24', 'Joshua', 21, 24, '&nbsp;ايالون او جات رِمون، چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5944, 'Joshua 21:25', 'Joshua', 21, 25, '&nbsp;د نمرپرېواتۀ طرف ته منسى د علاقې نه هغوئ له دوه ښارونه ورکړے شوى وُو، تعنک او جات رِمون، چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5945, 'Joshua 21:26', 'Joshua', 21, 26, '&nbsp;د قُهات قبيلې کورَنو ته ټول لس ښارونه مِلاو شول، چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5946, 'Joshua 21:27', 'Joshua', 21, 27, '&nbsp;د ليوى قوم يوې بلې قبيلې جيرسون ته د نمرخاتۀ په طرف منسى د علاقې نه دوه ښارونه مِلاو شول يعنې په بسن کښې جولان، چې د پناه يو ښار وو او بعستراه، چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5947, 'Joshua 21:28', 'Joshua', 21, 28, '&nbsp;د يساکار د علاقې نه هغوئ ته څلور ښارونه مِلاو شول، قِسيون، دبرت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5948, 'Joshua 21:29', 'Joshua', 21, 29, '&nbsp;يرموت او عين‌جنيم، چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5949, 'Joshua 21:30', 'Joshua', 21, 30, '&nbsp;د آشر د علاقې نه هغوئ ته څلور ښارونه مِلاو شول، مِسال، عبدون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5950, 'Joshua 21:31', 'Joshua', 21, 31, '&nbsp;حلقت او رِحوب چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5951, 'Joshua 21:32', 'Joshua', 21, 32, '&nbsp;د نفتالى د علاقې نه هغوئ ته درې ښارونه مِلاو شول، په ګليل کښې قادِس، چې د پناه يو ښار وو او د څرن زمکې ورسره وې، حمات دور او قرتان چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5952, 'Joshua 21:33', 'Joshua', 21, 33, '&nbsp;د جيرسون قبيلې مختلفو کورَنو ته ټول ديارلس ښارونه مِلاو شول چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5953, 'Joshua 21:34', 'Joshua', 21, 34, '&nbsp;د ليوى قبيلې د مرارى پاتې قبيلې ته د زبولون علاقې نه څلور ښارونه مِلاو شول، يقنِعام، قرتاه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5954, 'Joshua 21:35', 'Joshua', 21, 35, '&nbsp;دِمنه او نحلال چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5955, 'Joshua 21:36', 'Joshua', 21, 36, '&nbsp;د روبين علاقې نه هغوئ ته څلور ښارونه مِلاو شول، بصر، يهض،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5956, 'Joshua 21:37', 'Joshua', 21, 37, '&nbsp;قديمات او مفعت چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5957, 'Joshua 21:38', 'Joshua', 21, 38, '&nbsp;د جاد قبيلې نه هغوئ ته څلور ښارونه مِلاو شول، په جِلعاد کښې رامات، چې د پناه يو ښار وو، چې د څرن زمکې ورسره وې، محنايم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5958, 'Joshua 21:39', 'Joshua', 21, 39, '&nbsp;حسبون او يعزير چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5959, 'Joshua 21:40', 'Joshua', 21, 40, '&nbsp;نو د مرارى قبيلې ته ټول دولس ښارونه حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5960, 'Joshua 21:43', 'Joshua', 21, 43, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو له هغه ټول مُلک ورکړو د کوم يې چې د هغوئ پلار نيکۀ سره د ورکولو لوظ کړے وو. کله چې بنى اِسرائيلو دا مُلک قبضه کړو، نو هغوئ هلته په هغه مُلک کښې دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5961, 'Joshua 21:44', 'Joshua', 21, 44, '&nbsp;مالِک خُدائ هغوئ له هم هغه شان د هر طرف نه امن ورکړے وو، لکه څنګه چې هغۀ د هغوئ د پلار نيکۀ سره لوظ کړے وو. د هغوئ يو دشمن هم د هغوئ مقابله نۀ شوه کولے ځکه چې مالِک خُدائ هغوئ له په ټولو دشمنانو باندې فتح ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5962, 'Joshua 21:45', 'Joshua', 21, 45, '&nbsp;مالِک خُدائ چې د بنى اِسرائيلو سره څومره وعدې کړې وې نو په هغې کښې يوه هم نۀ وه ناکامه شوې او ټولې يې پوره کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5963, 'Joshua 22:1', 'Joshua', 22, 1, '&nbsp;بيا يشوَع د روبين، جاد او د نمرخاتۀ طرف منسى قبيلې خلق راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5964, 'Joshua 22:2', 'Joshua', 22, 2, '&nbsp;او يشوَع ورته وفرمائيل، ”تاسو هغه هر څۀ کړى دى چې د مالِک خُدائ خِدمت کوونکى موسىٰ د څۀ کولو حُکم درکړے دے او تاسو زما ټول حُکمونه منلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5965, 'Joshua 22:3', 'Joshua', 22, 3, '&nbsp;په دې ټولو وختونو کښې تاسو يو ځلې هم د خپلو بنى اِسرائيلو سره بې‌وفائى نۀ ده کړې. تاسو د مالِک خُدائ د خپل خُدائ پاک حُکم ښۀ منلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5966, 'Joshua 22:4', 'Joshua', 22, 4, '&nbsp;نو چې څنګه هغۀ وعده کړې ده، مالِک خُدائ ستاسو خُدائ پاک ستاسو خپلو بنى اِسرائيلو له آرام درکړے دے. نو په هغه مُلک کښې واپس خپلو کورونو ته لاړ شئ، کوم مُلک چې د اُردن نمرخاتۀ طرف ته دے، هغه مُلک چې د مالِک خُدائ خِدمت کوونکى موسىٰ درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5967, 'Joshua 22:5', 'Joshua', 22, 5, '&nbsp;خيال کوئ چې هغه قانون پوره ومنئ چې موسىٰ د هغې حُکم درکړے دے يعنې د مالِک خُدائ د خپل خُدائ پاک سره مينه کوئ، د هغۀ حُکمونه منئ، د هغۀ وفادار اوسئ او د زړۀ د اخلاصه د هغۀ خِدمت کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5968, 'Joshua 22:9', 'Joshua', 22, 9, '&nbsp;د روبين، جاد او نمرخاتۀ طرف ته منسى قبيلو خلق واپس خپلو کورونو ته لاړل. هغوئ پاتې بنى اِسرائيل د کنعان په مُلک سيلا کښې پرېښودل او خپل مُلک جِلعاد ته يې سفر شروع کړو، دا مُلک هغوئ د هغه حُکم په مطابق نيولے وو چې مالِک خُدائ د موسىٰ په ذريعه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5969, 'Joshua 22:10', 'Joshua', 22, 10, '&nbsp;خو په کوم وخت کښې چې هغوئ لا په کنعان کښې وُو او چې کله هغوئ د اُردن سره نزدې جليلوت نومې ځائ ته راغلل، نو د روبين، جاد او د منسى نيمې قبيلې سړى هلته د دې دپاره ايسار شول چې يوه لويه او د شان و شوکت والا قربان‌ګاه جوړه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5970, 'Joshua 22:11', 'Joshua', 22, 11, '&nbsp;باقى بنى اِسرائيلو ته ووئيلے شول چې، ”واورئ، د روبين، جاد او د منسى نيمې قبيلې کنعان مُلک ته ننوتلو په ځائ کښې، زمونږ په طرف باندې د اُردن سيند سره يوه قربان‌ګاه جوړه کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5971, 'Joshua 22:12', 'Joshua', 22, 12, '&nbsp;کله چې بنى اِسرائيل د دې نه خبر شول، نو د سيلا سره ټول قوم د دې دپاره راغونډ شو چې د نمرخاتۀ طرف ته قبيلو خِلاف جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5972, 'Joshua 22:13', 'Joshua', 22, 13, '&nbsp;نو بنى اِسرائيلو د اِلى‌عزر اِمام زوئ فينحاس د جِلعاد په مُلک کښې د روبين، جاد او د نمرخاتۀ طرف منسى قبيلې خلقو له ولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5973, 'Joshua 22:14', 'Joshua', 22, 14, '&nbsp;بيا لس مشران د فينحاس سره لاړل، چې هر يو د بنى اِسرائيلې قبيلې مشر وو او هر يو په قبيلو کښې د کورَنو مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5974, 'Joshua 22:15', 'Joshua', 22, 15, '&nbsp;هغوئ په جِلعاد کښې د روبين، جاد او د منسى نيمې قبيلې خلقو له راغلل او ورته يې ووئيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5975, 'Joshua 22:16', 'Joshua', 22, 16, '&nbsp;”د مالِک خُدائ ټول قوم تپوس کوى چې تاسو د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک خِلاف دا عمل ولې کړے دے؟ چې دا قربان‌ګاه تاسو د ځان دپاره جوړه کړې ده نو د مالِک خُدائ خِلاف مو بغاوت کړے دے او تاسو د هغۀ په لاره نۀ يئ روان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5976, 'Joshua 22:17', 'Joshua', 22, 17, '&nbsp;په فعور کښې زمونږ هغه ګناه درته ياده ده څۀ، چې په کوم وخت کښې مالِک خُدائ په خلقو وبا راوستله؟ مونږ د هغې په وجه تر اوسه پورې په تکليف کښې يُو. ولې هغه ګناه کافى نۀ وه څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5977, 'Joshua 22:18', 'Joshua', 22, 18, '&nbsp;تاسو اوس د هغۀ په لاره د تلو نه اِنکار کوئ څۀ؟ کۀ تاسو نن د مالِک خُدائ خِلاف سرکشى وکړه، نو سبا به هغه د بنى اِسرائيلو ټول قوم ته په قهر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5978, 'Joshua 22:19', 'Joshua', 22, 19, '&nbsp;نو بيا، کۀ ستاسو مُلک د عبادت دپاره ښۀ نۀ وى، نو د مالِک خُدائ مُلک ته ورننوځئ، چرته چې د هغۀ مقدسه خېمه ده. زمونږ په مينځ کښې په څۀ زمکه باندې دعوىٰ وکړئ. خو د مالِک خُدائ خِلاف سرکشى مۀ کوئ او نۀ چې مونږ سرکشه کړئ چې د مالِک خُدائ زمونږ د خُدائ پاک د قربان‌ګاه نه علاوه يوه قربان‌ګاه جوړه کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5979, 'Joshua 22:20', 'Joshua', 22, 20, '&nbsp;هغه راپه ياد کړئ چې د زارح زوئ عکن د هغه څيزونو سره خيانت وکړو چې د هغې تباهى ضرورى وه، د دې په وجه د بنى اِسرائيلو ټول قوم ته سزا مِلاو شوه. د عکن د ګناه په وجه نور کسان هم مړۀ شوى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5980, 'Joshua 22:21', 'Joshua', 22, 21, '&nbsp;د روبين، جاد او د منسى نيمې قبيلو خلقو د نمرپرېواتۀ طرف ته قبيلو د کورَنو مشرانو ته په جواب کښې ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5981, 'Joshua 22:22', 'Joshua', 22, 22, '&nbsp;”خُدائ پاک طاقتور دے. هغه مالِک خُدائ دے. خُدائ پاک طاقتور دے. هغه مالِک خُدائ دے. هغۀ ته پته ده چې مونږ داسې ولې وکړل او مونږ غواړُو چې تاسو ته هم پته ولګى. کۀ مونږ سرکشى وکړه او په مالِک خُدائ باندې مو ايمان ونۀ لرلو، نو مونږ نور ژوندى مۀ پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5982, 'Joshua 22:23', 'Joshua', 22, 23, '&nbsp;کۀ مونږ د مالِک خُدائ نافرمانى وکړه او د دې دپاره مو خپله قربان‌ګاه جوړه کړه چې په دې باندې نذرانې وسوزوو او يا يې د غلې نذرانې او سلامتۍ نذرانې دپاره استعمال کړُو، نو مالِک خُدائ دې په خپله مونږ له سزا راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5983, 'Joshua 22:24', 'Joshua', 22, 24, '&nbsp;مونږ داسې ځکه وکړل چې په راتلونکى وختونو کښې ستاسو اولاد زمونږ اولاد ته ونۀ وائى چې ستاسو د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک سره هيڅ کار نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5984, 'Joshua 22:25', 'Joshua', 22, 25, '&nbsp;هغۀ زمونږ او ستاسو يعنې د روبين او جاد خلقو په مينځ کښې د اُردن د حد پوله جوړه کړه. ستاسو د مالِک خُدائ سره هيڅ کار نشته. نو بيا کېدے شى چې ستاسو اولاد زمونږ اولاد د مالِک خُدائ د عبادت نه منع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5985, 'Joshua 22:26', 'Joshua', 22, 26, '&nbsp;نو مونږ قربان‌ګاه د نذرانو سوزولو او پېش کولو دپاره نۀ ده جوړه کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5986, 'Joshua 22:27', 'Joshua', 22, 27, '&nbsp;بلکې د دې دپاره مو جوړه کړه چې دا زمونږ او ستاسو او زمونږ نه پس د نسلونو دپاره يو يادګار وى، چې مونږ بې‌شکه د مالِک خُدائ د مقدسې خېمې په مخکښې د هغۀ عبادت کوُو او هغۀ ته خپلې نذرانې وسوزوو او قربانۍ او د سلامتۍ نذرانې پېش کوُو. نو داسې ستاسو اولاد به دا خبره نۀ کوى چې د مالِک خُدائ سره زمونږ هيڅ کار نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5987, 'Joshua 22:28', 'Joshua', 22, 28, '&nbsp;زمونږ خيال دا وو، کۀ چرې داسې وشول، نو زمونږ اولاد به وائى چې ګورئ، زمونږ پلار نيکۀ هم هغه شان قربان‌ګاه جوړه کړې ده لکه څنګه چې د مالِک خُدائ قربان‌ګاه ده، دا د سوزېدونکو نذرانو او قربانو دپاره نۀ ده بلکې دا زمونږ او ستاسو د خلقو دپاره يو يادګار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5988, 'Joshua 22:29', 'Joshua', 22, 29, '&nbsp;مونږ به بېخى د مالِک خُدائ خِلاف سرکشى نۀ کوُو او نۀ به د هغۀ نه اوړو چې د نذرانو د سوزېدو او غلې او د قربانو پېش کولو دپاره يوه قربان‌ګاه جوړه کړُو. کومه قربان‌ګاه چې د مالِک خُدائ زمونږ خُدائ پاک د حضور خېمې په مخکښې ولاړه ده نو صرف هغه به د دې دپاره استعمالولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5989, 'Joshua 22:30', 'Joshua', 22, 30, '&nbsp;فينحاس اِمام او د قوم هغه لس مشران سړى کوم چې د هغۀ سره وُو، د نمرپرېواتۀ طرف ته د قبيلو د کورَنو مشران د روبين، جاد او د منسى نيمې قبيلې د خبرو نه خبر شول، نو هغوئ خوشحاله شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5990, 'Joshua 22:31', 'Joshua', 22, 31, '&nbsp;د اِلى‌عزر اِمام زوئ فينحاس هغوئ ته ووئيل، ”اوس مونږ ته پته ده چې مالِک خُدائ زمونږ مل دے. تاسو د هغۀ خِلاف سرکشى ونۀ کړه، نو داسې تاسو بنى اِسرائيل د مالِک خُدائ د سزا نه بچ کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5991, 'Joshua 22:32', 'Joshua', 22, 32, '&nbsp;بيا فينحاس او مشران د جِلعاد په مُلک کښې د روبين او جاد د خلقو نه روان شول او واپس په کنعان کښې د بنى اِسرائيلو خلقو له لاړل او هغوئ يې خبر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5992, 'Joshua 22:33', 'Joshua', 22, 33, '&nbsp;بنى اِسرائيل خوشحاله وُو او د خُدائ پاک ثناء صِفت يې کولو. هغوئ جنګ له د تلو او هغه خبرې پرېښودې چې هغه مُلک به تباه کړُو چرته چې د روبين او جاد خلق اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5993, 'Joshua 22:34', 'Joshua', 22, 34, '&nbsp;د روبين او جاد خلقو ووئيل، ”دا قربان‌ګاه زمونږ ټولو دپاره يو يادګار دے چې مالِک خُدائ، خُدائ پاک دے.“ نو هغوئ په دې باندې ”يادګار“ نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5994, 'Joshua 23:1', 'Joshua', 23, 1, '&nbsp;ډېره موده وروستو مالِک خُدائ بنى اِسرائيلو له د هغوئ ګېرچاپېره دشمنانو نه امن ورکړو. په هغه وخت کښې يشوَع ډېر بوډا وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5995, 'Joshua 23:2', 'Joshua', 23, 2, '&nbsp;نو هغۀ ټول بنى اِسرائيل، مشران، مالِکان، قاضيان او د خلقو آفسران راوغوښتل او ورته يې ووئيل، ”زۀ اوس ډېر بوډا شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5996, 'Joshua 23:3', 'Joshua', 23, 3, '&nbsp;تاسو هغه هر څۀ ليدلى دى چې مالِک خُدائ ستاسو خُدائ پاک د دې ټولو قومونو سره ستاسو دپاره کړى دى. مالِک خُدائ ستاسو خُدائ پاک ستاسو دپاره جنګ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5997, 'Joshua 23:4', 'Joshua', 23, 4, '&nbsp;ما ستاسو قبيلو ته د هغه قومونو مُلک حواله کړے دے چې خپل ميراث يې شى کومو قومونو چې شکست نۀ دے خوړلے او ورسره د هغه ټولو قومونو چې ما د مخکښې نه فتح کړى دى، چې هغوئ د نمرخاتۀ طرف ته د اُردن سيند نه واخله د نمرپرېواتۀ طرف ته د مديترانى سمندر پورې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5998, 'Joshua 23:5', 'Joshua', 23, 5, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به هغه پاتې شوى قومونه ستاسو نه په شا کړى او چې تاسو مخ په وړاندې ځئ نو هغوئ به وشړئ. د هغوئ مُلک به ستاسو شى، هم هغه شان لکه څنګه چې مالِک خُدائ ستاسو خُدائ پاک وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5999, 'Joshua 23:6', 'Joshua', 23, 6, '&nbsp;نو پام کوئ چې هغه هر څۀ ومنئ او هغه هر څۀ وکړئ کوم چې د موسىٰ د شريعت په کِتاب کښې ليکلے شوى دى او د هغې نه يو طرف ته هم مۀ اوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6000, 'Joshua 23:7', 'Joshua', 23, 7, '&nbsp;نو بيا به تاسو د هغه خلقو سره کار نۀ لرئ کوم چې ستاسو سره پاتې وى، نۀ به د هغوئ د معبودانو نومونه په ژبه راولئ، او نۀ به دا نومونه د قسم دپاره استعمالوئ، نۀ به د هغه معبودانو عبادت کوئ او نۀ به ورته سجده لګوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');